mapper.select:
select m.msg_id as msgId, m.msg_type as type, m.msg_title as title, m.msg_content as content, m.msg_is_read as isRead, date_format(m.msg_read_at, '%Y-%m-%d %H:%i') as readAt, date_format(m.msg_created_at, '%Y-%m-%d %H:%i') as createdAt, u.nick_name as receiverName from t_msg m left join sys_user u on u.user_id = m.msg_receiver_id where m.msg_sender_id = 0
and u.nick_name like concat('%', #{candidate}, '%')
and m.msg_type = #{scene}
and m.msg_created_at >= #{from}
and m.msg_created_at <= #{to}
order by m.msg_created_at desc
